(() => {
  'use strict';
  const R=window.ReviewModel,M=window.MatModel,I=window.ReviewImport,P=window.ReviewPromotions;
  const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),fileInput=document.querySelector('#file-input');
  const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
  const money=v=>Number.isFinite(v)?'¥'+n(v):'—';
  const icon=name=>`<i data-lucide="${name}" class="icon" aria-hidden="true"></i>`;
  const btn=(a,text,ic='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${a}" ${extra}>${ic?icon(ic):''}${e(text)}</button>`;
  const ib=(a,text,ic,extra='')=>`<button type="button" class="icon-btn" data-action="${a}" aria-label="${e(text)}" title="${e(text)}" ${extra}>${icon(ic)}</button>`;
  const opt=(v,text,selected)=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(text)}</option>`;
  const field=(label,name,value,type='number',extra='')=>`<label class="field"><span>${e(label)}</span><input type="${type}" name="${name}" value="${e(value)}" ${type==='number'?'step="any"':''} ${extra}></label>`;
  const select=(label,name,options)=>`<label class="field"><span>${e(label)}</span><select name="${name}">${options}</select></label>`;
  let state,view=new URLSearchParams(location.search).get('view')==='product'?'product':'work',tab='sku',libTab='strategies',modal=null,focusBefore=null,fileKind='',busy=false,conflict=false,saveError='',savedRaw=null,salesDraft=null,undoSales=null,selectedProducts=new Set(),productFilter='all',productPage=0,productMore=false,productUnwritten=false,productUndo=null,menuOpen=false,skuOptionsOpen=false,showDeletedRules=false,toastTimer;
  try{savedRaw=localStorage.getItem(R.KEY);state=R.migrate(savedRaw?JSON.parse(savedRaw):R.seed());if(!R.validState(state))throw Error('原型草稿结构不正确，请先导出原始草稿后重置');}
  catch(err){state=null;saveError=err.message;}
  const shop=()=>state.shops.find(s=>s.id===state.activeShop);
  const sizeLabel=id=>M.sizeLabel(state.sizes.find(s=>s.id===id));
  const rulesFor=id=>state.materials.find(m=>m.id===id)?.weightRules||[];
  const ruleLabel=r=>(r.thickness===''?'标准':r.thickness+' mm')+(r.variant?' · '+r.variant:'');
  const materialOptions=id=>state.materials.filter(m=>!m.deleted||m.id===id).map(m=>opt(m.id,m.name+(m.deleted?'（已删除）':''),id)).join('');
  const transferRulesFor=material=>state.materials.find(m=>m.name===material)?.weightRules.filter(r=>!r.variant)||[];
  const thicknessValue=r=>r.thicknessStatus==='value'?r.resolvedThicknessRuleId:'__pending';
  function toast(message,undo=false){const t=document.querySelector('#toast');t.textContent=message;if(undo){const button=document.createElement('button');button.type='button';button.dataset.action='product-undo';button.textContent='撤销';t.append(button);}t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),undo?10000:4500);}
  function persist(){
    if(conflict){saveError='其他窗口已更新原型，请导出本页草稿后重新载入。';return false;}
    try{state.shops.forEach(R.syncPlan);const disk=localStorage.getItem(R.KEY);if(disk!==savedRaw){conflict=true;throw Error('其他窗口已更新原型，请导出草稿后重新载入。');}state.revision++;const raw=JSON.stringify(state);localStorage.setItem(R.KEY,raw);savedRaw=raw;saveError='';return true;}catch(err){saveError='保存失败：'+err.message;return false;}
  }
  function commit(message=''){const ok=persist();render();if(message)toast(ok?message:saveError);}
  function download(bytes,name,type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([bytes],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  function summary(s){if(s.mode==='area')return `${s.baseArea}㎡起 ${s.baseMargin}% · 每满 ${s.stepArea}㎡ +${s.stepPoints} 个百分点 · 上限 ${s.cap}%`;if(s.mode==='fixed')return `所有规格目标毛利 ${s.margin}%`;return s.tiers.map((t,i)=>`第 ${i+1} 档 ${t}%`).join(' / ')+` · 其余 ${s.fallback}%`;}
  function nav(){return `<aside class="sidebar ${menuOpen?'menu-open':''}"><a class="brand" href="#" data-action="nav" data-view="work" aria-label="地垫工作台首页"><span class="brand-mark"><img src="assets/app-icon.png" width="34" height="34" alt=""></span><div><div class="brand-title">地垫工作台</div><div class="brand-sub">全域投放 · 盈亏测算</div></div></a>${btn('menu','导航','menu','mobile-menu','aria-expanded="'+menuOpen+'"')}<div class="shop-picker"><label for="active-shop">当前店铺</label><div class="row"><select id="active-shop" name="activeShop">${state.shops.map(s=>opt(s.id,s.name,state.activeShop)).join('')}</select>${ib('new-shop','新增店铺','plus')}</div></div><div class="shop-picker plan-picker"><label for="active-plan">当前计划</label><div class="row"><select id="active-plan" name="activePlan" ${shop().activePlanId?'':'disabled'}>${shop().activePlanId?shop().plans.filter(p=>!p.deleted).map(p=>opt(p.id,p.name,shop().activePlanId)).join(''):opt('','暂无计划','')}</select>${ib('plan-manage','管理计划','ellipsis')}</div></div><nav class="nav-group" aria-label="主导航">${[['work','投放测算','layout-dashboard'],['ledger','总账','chart-no-axes-combined'],['library','可复用规则','library'],['product','商品转表','table-2']].map(([v,label,ic])=>btn('nav',label,ic,'nav-item '+(view===v?'active':''),`data-view="${v}" ${view===v?'aria-current="page"':''}`)).join('')}</nav><div class="sidebar-bottom">${btn('nav','备份与迁移','file-spreadsheet','nav-item '+(view==='data'?'active':''),'data-view="data"')}<div class="local-status"><span class="status-dot"></span>独立原型 · 本机草稿</div><div class="view-label">沿用正式版界面 · 09.18</div></div></aside>`;}
  function header(title,subtitle,actions=''){return `<div class="page-header"><div class="page-heading"><h1>${e(title)}</h1><p class="page-sub">${e(subtitle)}</p></div><div class="row">${actions}</div></div>`;}
  const metricLabels={roi:'整体支付 ROI 保本线',profit:'预估盈亏',gmv:'整体成交金额',investment:'总投入',price:'平均售价',cost:'平均每单成本'};
  function metricValue(key,res){return key==='roi'?(res.valid&&res.roi===null?'无法保本':n(M.ceilRoi(res.roi))):money(res[key]);}
  function metrics(res){return `<div class="metric-toolbar"><h2>当前测算</h2>${btn('metrics','显示设置','sliders-horizontal','ghost')}</div><div class="metric-grid" data-count="${state.prefs.metrics.length}">${state.prefs.metrics.map(key=>`<section class="metric"><div class="metric-label">${metricLabels[key]}</div><div class="metric-value ${key==='profit'?(res.profit<0?'negative':'positive'):''}">${metricValue(key,res)}</div><div class="metric-desc">${{roi:'按退款后收入与履约成本计算',profit:'已扣广告及已填费用',gmv:'广告消耗 × 支付 ROI',investment:'商品、广告和各项已填费用',price:'按订单占比加权',cost:'计入退款影响，未含广告'}[key]}</div></section>`).join('')}</div>`;}
  function param(label,key,percent=false,refund=false){const value=refund?shop().params.refundRates[key]:shop().params[key];return `<label class="field"><span class="field-label">${label}${percent?' / %':''}</span><input type="number" name="param-${key}" data-param="${key}" ${refund?'data-refund="1"':''} value="${e(value)}" step="any" min="0" ${percent?'max="100"':''}></label>`;}
  function rail(){return `<aside class="parameter-rail" aria-label="投放与费用"><section class="rail-section"><div class="section-head"><h2>投放与费用</h2><span class="tag">改动即试算</span></div><div class="fields">${param('广告消耗 / 元','spend')}${param('支付 ROI','actualRoi')}</div></section><section class="rail-section fee-section"><div class="fields">${param('平台扣点','fee',true)}${param('税点','tax',true)}${param('退货回收比例','recovery',true)}</div></section><section class="rail-section"><h3>退款情况</h3><div class="fields stack-gap">${param('未发货退款','unshipped',true,true)}${param('已发货仅退款','shippedOnly',true,true)}${param('退货退款','returnRefund',true,true)}${param('1 小时内退款','firstHour',true,true)}</div></section><details class="advanced"><summary>其他费用</summary><div class="fields stack-gap">${param('其他费用 / 元每单','other')}${param('每退货单额外费用 / 元','returnCost')}</div></details></aside>`;}
  function resources(){const s=shop();return `<div class="sku-options-body"><div class="reuse-selects">
    <select name="defaultMaterial" aria-label="默认材料">${state.materials.filter(m=>!m.deleted||m.id===s.materialId).map(m=>opt(m.id,'材质 · '+m.name+(m.deleted?'（已删除）':''),s.materialId)).join('')}</select>
    <select name="defaultRule" aria-label="厚度">${rulesFor(s.materialId).filter(r=>!r.variant).map(r=>opt(r.id,'厚度 · '+ruleLabel(r),s.ruleId)).join('')}</select>
    <select name="shippingId" aria-label="运费模板">${state.shippingTemplates.filter(t=>!t.deleted||t.id===s.shippingId).map(t=>opt(t.id,'运费 · '+t.name+(t.deleted?'（已删除）':''),s.shippingId)).join('')}</select>
    <select name="strategyId" aria-label="定价策略">${opt('','定价 · 手动定价',s.strategyId)}${state.strategies.filter(x=>(x.active&&!x.deleted)||x.id===s.strategyId).map(x=>opt(x.id,'定价 · '+x.name+(x.deleted?'（已删除）':!x.active?'（停用）':''),s.strategyId)).join('')}</select>
    <select name="sizeSchemeId" aria-label="选用尺寸方案">${opt('','选用尺寸方案','')}${state.sizeSchemes.filter(x=>!x.deleted).map(x=>opt(x.id,x.name+' · '+x.sizeIds.length+' 个尺寸','')).join('')}</select>
    </div><div class="sku-options-actions">${btn('size-scheme-save','保存当前尺寸方案','save')}${btn('sales','导入销售情况','upload')}${btn('listing-calculator','上架价格计算器','calculator')}${s.strategyId&&s.rows.some(r=>r.priceMode==='manual')?btn('restore-all','全部恢复策略价','','ghost'):''}</div></div>`;}
  function skuTable(res){const s=shop(),strategy=state.strategies.find(x=>x.id===s.strategyId),manual=s.rows.filter(r=>r.priceMode==='manual').length;return `<div class="section-head review-toolbar"><div class="row"><h2>商品规格</h2><span class="tag">${res.rows.length} 个</span><button type="button" class="sku-options-toggle" data-action="sku-options" aria-expanded="${skuOptionsOpen}" aria-controls="sku-options">${skuOptionsOpen?'收起':'展开'}设置${icon(skuOptionsOpen?'chevron-up':'chevron-down')}</button></div><div class="row">${btn('columns','显示设置','sliders-horizontal','ghost')}${btn('add-sku','添加规格','plus')}</div></div><div id="sku-options" ${skuOptionsOpen?'':'hidden'}>${resources()}</div>${res.rows.length?`<div class="table-scroll"><table class="sku-table review-table"><caption class="sr-only">商品规格、售价和毛利率</caption><thead><tr><th scope="col">商品规格</th>${state.prefs.columns.map(k=>`<th scope="col" class="num">${R.columns[k]}</th>`).join('')}<th scope="col">操作</th></tr></thead><tbody>${res.rows.map(r=>`<tr data-sku="${r.id}"><td><div class="sku-title"><button type="button" data-action="edit-sku" data-id="${r.id}">${e(M.sizeLabel(r.size))}</button></div><div class="sku-sub">${e(r.mat.name)} · ${e(ruleLabel(r.rule))} · ${n(r.area,2)}㎡<br>${e(r.skuId||'未绑定 SKU ID')}</div>${r.priceErrors.length?`<div class="row-error">${e(r.priceErrors.join('；'))}</div>`:''}</td>${state.prefs.columns.map(k=>skuCell(k,r)).join('')}<td class="actions-cell">${ib('remove-sku','移除 '+M.sizeLabel(r.size),'x',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="total-row"><span>按生产尺寸计成本，毛利率不扣广告与退款。</span><div class="row"><span class="${Math.abs(res.total-100)>1e-6?'negative':''}">订单占比合计 ${n(res.total,2)}%</span>${ib('normalize','调整占比至 100%','equal')}</div></div>`:empty('还没有商品规格','添加尺寸后，所选方案会自动计算售价。','add-sku','添加规格')}${s.salesSource?`<div class="strategy-line"><span>销售来源：${e(s.salesSource.filename)} · ${e(s.salesSource.period)} · 按${s.salesSource.basis} · ${n(s.salesSource.count,0)}</span>${undoSales?.shopId===s.id?btn('undo-sales','撤销本次导入','undo-2','ghost'):''}</div>`:''}${res.errors.length?`<div class="message-error" role="status">${e(res.errors.slice(0,5).join('；'))}</div>`:''}<details class="inline-info"><summary>查看定价与毛利口径</summary><p>售价 =（材料成本 + 单次运费）÷（1 − 目标毛利率 − 平台扣点 − 税点）。此售价为用户最终到手价，向上保留两位小数；活动前的上架价在上架价格计算器中反推。退款、广告及其他费用仍计入上方盈亏测算；手动售价不会被方案更新覆盖。</p></details>`;}
  function skuCell(k,r){
    if(k==='price')return `<td class="num"><input type="number" name="price-${r.id}" data-row="${r.id}" data-key="price" aria-label="${e(M.sizeLabel(r.size))} 售价" min="0.01" step="0.01" value="${e(r.price??'')}"><div class="cell-meta price-mode"><span class="${r.priceMode==='manual'?'mode-manual':''}">${r.priceMode==='manual'?'手动':'策略价'}</span>${r.priceMode==='manual'&&shop().strategyId?`<button type="button" data-action="restore-price" data-id="${r.id}">恢复</button>`:''}</div></td>`;
    if(k==='share')return `<td class="num"><input type="number" name="share-${r.id}" data-row="${r.id}" data-key="share" aria-label="${e(M.sizeLabel(r.size))} 订单占比" min="0" max="100" step="any" value="${r.share}"></td>`;
    if(k==='margin')return `<td class="num ${r.margin<0?'negative':''}">${n(r.margin)}<div class="margin-target">${r.priceMode==='auto'&&r.target!==null?'目标 '+n(r.target,0)+'%':'按当前售价'}</div></td>`;
    return `<td class="num">${k==='weight'?n(r.weight*1000,0):k==='sales'?n(r.sales,0):k==='roi'?n(M.ceilRoi(r.roi)):money(r[k])}</td>`;
  }
  function empty(title,note,action='',label=''){return `<div class="review-empty"><h3>${e(title)}</h3><p>${e(note)}</p>${action?btn(action,label,'plus'):''}</div>`;}
  function workPage(){if(!shop().activePlanId)return header(shop().name+' · 投放测算','')+`<section class="plan-detail-card">${empty('暂无计划','新建计划，或从已删除列表恢复。','plan-new','新建计划')}${btn('plan-manage','查看已删除计划','rotate-ccw','ghost')}</section>`;const res=R.calculate(state);return header(shop().name+' · 投放测算','修改参数即时测算，确认入账后计入当前店铺总账。',btn('entry','确认入账','book-check','confirm-entry'))+`<div class="content-grid plan-overview"><section class="main-column"><div id="metrics">${metrics(res)}</div></section>${rail()}</div><section class="plan-detail-card"><nav class="tabs" aria-label="测算视图">${[['sku','尺寸与售价'],['chart','投入与利润'],['history','历史账本']].map(([v,t])=>`<button type="button" class="tab ${v===tab?'active':''}" data-action="tab" data-tab="${v}">${t}</button>`).join('')}</nav>${tab==='sku'?skuTable(res):tab==='chart'?chart():ledgerTable(state.records.filter(r=>r.shopId===state.activeShop))}</section><footer class="page-footer"><span>手动估算 · 非结算利润</span><span>当前规则用于测算，入账数据按当时值保留。</span></footer>`;}
  function libraryPage(){
    const labels={strategies:'定价策略',sizeSchemes:'尺寸方案',promotionSchemes:'活动方案',materials:'材料规则',sizes:'尺寸库',shipping:'运费模板'},kind=libTab==='shipping'?'shippingTemplates':libTab;
    const visible=state[kind].filter(x=>showDeletedRules?x.deleted:!x.deleted);
    const actions=(x,edit,copy='')=>x.deleted?btn('rule-restore','恢复','rotate-ccw','ghost',`data-kind="${kind}" data-id="${x.id}"`):`${edit?btn(edit,'编辑','pencil','ghost',`data-id="${x.id}"`):''}${copy?btn(copy,'复制','copy','ghost',`data-id="${x.id}"`):''}${btn('rule-delete','删除','trash-2','ghost danger',`data-kind="${kind}" data-id="${x.id}"`)}`;
    let heads=[],rows='';
    if(libTab==='strategies'){heads=['方案名称','类型 / 参数','操作'];rows=visible.map(x=>`<tr><td><strong>${e(x.name)}</strong></td><td><div class="rule-type">${R.modes[x.mode]}</div><div class="rule-summary">${e(summary(x))}</div></td><td>${actions(x,'strategy-edit','strategy-copy')}</td></tr>`).join('');}
    if(libTab==='sizeSchemes'){heads=['方案名称','包含尺寸','操作'];rows=visible.map(x=>`<tr><td><strong>${e(x.name)}</strong><div class="cell-meta">${x.sizeIds.length} 个尺寸</div></td><td><div class="rule-summary">${x.sizeIds.map(id=>e(sizeLabel(id))).join('、')}</div></td><td>${actions(x,'size-scheme-edit','size-scheme-copy')}</td></tr>`).join('');}
    if(libTab==='promotionSchemes'){heads=['方案名称','叠加顺序','操作'];rows=visible.map(x=>`<tr><td><strong>${e(x.name)}</strong></td><td><div class="rule-summary">${e(promotionSummary(x))}</div></td><td>${actions(x,'promotion-edit','promotion-copy')}</td></tr>`).join('');}
    if(libTab==='materials'){heads=['材料名称','厚度 / 成本 / 重量系数','操作'];rows=visible.map(x=>`<tr><td><strong>${e(x.name)}</strong></td><td><div class="rule-summary">${x.weightRules.map(r=>`${e(ruleLabel(r))}：${money(r.costPerSqm)} / ㎡ · ${n(r.coefficient)} kg/㎡`).join('<br>')}</div></td><td>${actions(x,'material-edit')}</td></tr>`).join('');}
    if(libTab==='sizes'){heads=['尺寸','生产面积','类型','操作'];rows=visible.map(x=>`<tr><td>${e(M.sizeLabel(x))}</td><td>${n(M.productionArea(x))}㎡</td><td>${x.irregular?'异形':'矩形'}</td><td>${actions(x,'size-edit')}</td></tr>`).join('');}
    if(libTab==='shipping'){heads=['模板名称','规则','操作'];rows=visible.map(x=>`<tr><td><strong>${e(x.name)}</strong></td><td><div class="rule-summary">${x.type==='regional'?'中通常规重量分档 · 偏远地区单独核价':`每单 ${money(x.fee)}`}</div></td><td>${actions(x,x.type==='fixed'?'shipping-edit':'')}</td></tr>`).join('');}
    const newActions={strategies:'strategy-new',sizeSchemes:'size-scheme-new',promotionSchemes:'promotion-new',materials:'material-new',sizes:'size-new',shipping:'shipping-new'};
    return header('可复用规则','在这里编辑规则细节，使用时直接选用已保存方案。',btn(newActions[libTab],'新增'+labels[libTab],'plus','primary'))+`<section class="wide-content"><nav class="tabs" aria-label="规则分类">${Object.entries(labels).map(([k,v])=>`<button type="button" class="tab ${libTab===k?'active':''}" data-action="library-tab" data-tab="${k}">${v}</button>`).join('')}</nav><div class="rule-list-toolbar"><label><input type="checkbox" name="showDeletedRules" ${showDeletedRules?'checked':''}>显示已删除</label></div>${visible.length?`<div class="table-scroll"><table class="library-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`:empty(showDeletedRules?'没有已删除的规则':'还没有'+labels[libTab],showDeletedRules?'删除后可在这里恢复。':'点击右上角新增。')}</section>`;
  }
  const shortProductId=id=>{const chars=Array.from(String(id));return chars.length>10?chars.slice(0,6).join('')+'…'+chars.slice(-4).join(''):String(id);};
  function productSelection(){
    const all=state.product?.rows||[],filtered=all.filter(r=>!productUnwritten||!(r.thicknessCandidates||[]).length);
    const matching=filtered.filter(r=>productFilter==='all'||(productFilter==='pending'?r.issues.length:!r.issues.length));
    const ordered=I.productGroups({rows:matching}).flatMap(g=>g.rows),pages=Math.max(1,Math.ceil(ordered.length/50));productPage=Math.max(0,Math.min(productPage,pages-1));
    return {all,filtered,matching,shown:ordered.slice(productPage*50,productPage*50+50),pages};
  }
  function productGroupState(g){
    const first=g.rows[0],material=g.rows.every(r=>r.materialStatus!=='pending'&&r.material===first.material)?first.material:'__mixed';
    const targets=g.rows.filter(r=>r.dimensionStatus!=='blank'),enabled=material&&material!=='__mixed'&&targets.length>0;
    const rule=enabled&&targets.every(r=>r.resolvedThicknessRuleId&&r.resolvedThicknessRuleId===targets[0].resolvedThicknessRuleId)?targets[0].resolvedThicknessRuleId:'__pending';
    return {material,enabled,rule};
  }
  function productGroupView(g,index,visible){
    const {material,enabled,rule}=productGroupState(g),hidden=g.rows.length-visible.length;
    const scope=`${g.platform||'未提供平台'} / ${g.shop||'未提供店铺'}；同链接全部 ${g.rows.length} 个 SKU${hidden?'（含 '+hidden+' 条筛选或分页隐藏行）':''}；统一所选字段，尺寸保持原值。`;
    return `<tr class="transfer-group" data-product-group="${index}"><td><input type="checkbox" name="product-group-${index}" data-product-group-select="${index}" aria-label="选择商品 ${e(g.productId)} 当前页显示的规格" ${visible.every(r=>selectedProducts.has(r.id))?'checked':''}></td><td><div class="transfer-group-heading"><span class="transfer-group-id" title="${e(g.productId||'未提供商品 ID')}" tabindex="0" aria-label="商品 ID ${e(g.productId||'未提供')}">ID ${e(g.productId?shortProductId(g.productId):'未提供')}</span><span class="transfer-group-hint" title="${e(scope)}">同链接批量处理</span></div><div class="cell-meta">共 ${g.rows.length} 个 SKU${hidden?' · 含隐藏 '+hidden+' 条':''}</div></td><td><select name="product-group-material-${index}" data-product-group-material="${index}" aria-label="同链接全部 SKU 材质" title="${e(scope)}" ${busy?'disabled':''}>${material==='__mixed'?opt('__mixed','请选择',material):''}${opt('__blank','保留为空',material===''?'__blank':material)}${state.materials.filter(m=>!m.deleted||m.name===material).map(m=>opt(m.name,m.name,material)).join('')}</select></td><td><select name="product-group-thickness-${index}" data-product-group-thickness="${index}" aria-label="同链接全部 SKU 厚度" title="${e(scope)}" ${!enabled||busy?'disabled':''}>${opt('__pending',enabled?'批量选择':material==='__mixed'?'先统一材质':'无需计算',rule)}${enabled?transferRulesFor(material).map(r=>opt(r.id,ruleLabel(r),rule)).join(''):''}</select></td><td colspan="4"></td></tr>`;
  }
  function productRowView(r){
    const blank=r.materialStatus==='blank'||r.dimensionStatus==='blank',matValue=r.materialStatus==='pending'?'__pending':r.materialStatus==='blank'?'__blank':r.material,dimValue=r.dimensionStatus==='pending'?'__pending':r.dimensionStatus==='blank'?'__blank':'__value';
    return `<tr data-product-row="${e(r.id)}"><td><input type="checkbox" name="selected-${r.id}" data-selected="${r.id}" aria-label="选择第 ${r.rowNumber} 行" ${selectedProducts.has(r.id)?'checked':''}></td><td class="source-text"><p>${e(r.originalName)}</p><p class="note">${e(r.originalSpec)}</p><div class="cell-meta">${e(r.values[18])} · 原表第 ${r.rowNumber} 行</div></td><td><select name="material-${r.id}" data-product-material="${r.id}" aria-label="第 ${r.rowNumber} 行材质" class="${r.materialStatus==='pending'?'needs-review':''}" ${busy?'disabled':''}>${r.materialStatus==='pending'?opt('__pending','待确认',matValue):''}${opt('__blank','保留为空',matValue)}${state.materials.filter(m=>!m.deleted||m.name===r.material).map(m=>opt(m.name,m.name+(m.deleted?'（已删除）':''),matValue)).join('')}</select><div class="cell-meta ${r.materialStatus==='pending'?'status-pending':''}">${r.materialStatus==='blank'?'已确认留空':r.materialStatus==='pending'?(r.pseudo?'伪亚麻，需人工确认':r.candidates.length>1?'多个材质候选':'需人工确认'):r.materialSource==='manual'?'人工确认':'自动识别'}</div></td><td><select name="thickness-${r.id}" data-product-thickness="${r.id}" aria-label="第 ${r.rowNumber} 行厚度" class="${r.thicknessStatus==='pending'?'needs-review':''}" ${busy||r.materialStatus!=='value'||blank?'disabled':''}>${opt('__pending',blank?'无需计算':r.materialStatus==='value'?'请选择厚度':'先确认材质',thicknessValue(r))}${!blank?transferRulesFor(r.material).map(rule=>opt(rule.id,ruleLabel(rule),thicknessValue(r))).join(''):''}</select><div class="cell-meta ${r.thicknessStatus==='pending'?'status-pending':''}">${blank?'已留空，无需计算':r.thicknessStatus==='value'?e(r.thicknessSource):r.materialStatus==='value'?(r.thicknessCandidates?.length?`原文：${e(r.thicknessCandidates.join(' / '))} mm`:'原文未写厚度'):'先确认材质'}</div></td><td><select name="dimension-${r.id}" data-product-dimension="${r.id}" aria-label="第 ${r.rowNumber} 行尺寸" class="${r.dimensionStatus==='pending'?'needs-review':''}" ${busy?'disabled':''}>${r.dimensionStatus==='pending'?opt('__pending','待确认',dimValue):''}${opt('__blank','保留为空',dimValue)}${r.dimensionStatus==='value'?opt('__value',r.dimensions.width+' × '+r.dimensions.length,dimValue):''}${r.dimensionCandidates.map((d,i)=>opt(i,d.label,'')).join('')}${opt('__manual','手动输入…','')}</select><div class="cell-meta">${r.dimensionStatus==='blank'?'已确认留空':r.dimensionStatus==='pending'?'多个尺寸或未确认':n(r.values[8],3)+' ㎡'}</div></td><td class="num">${r.values[11]===''?'—':n(r.values[11],3)}</td><td class="num">${r.values[12]===''?'—':n(r.values[12])}</td><td><span class="${r.issues.length?'status-pending':'status-ok'}">${r.issues.length?'待复核':blank?'已留空':'已确认'}</span>${r.issues.length?`<div class="row-error">${e(r.issues.join('；'))}</div>`:''}</td></tr>`;
  }
  function productPageView(){
    const result=state.product;if(result)I.recalculateProducts(result,state);
    const {all,filtered,matching,shown,pages}=productSelection(),visibleIds=new Set(shown.map(r=>r.id));selectedProducts=new Set([...selectedProducts].filter(id=>visibleIds.has(id)));
    const pending=filtered.filter(r=>r.issues.length).length;
    const body=result?I.productGroups(result).map((g,i)=>{const visible=g.rows.filter(r=>visibleIds.has(r.id));return visible.length?productGroupView(g,i,visible)+visible.map(productRowView).join(''):'';}).join(''):'';
    return header('商品转表','按商品复核材质、厚度和尺寸，自动计算重量与成本。',btn('product-export','导出商品表','download','primary',!result?.summary.ready||busy?'disabled':''))+`<section class="wide-content integrated-transfer"><div class="transfer-file-strip"><div><strong>${result?e(result.filename||'识别复核示例'):'导入 ERP 商品规格'}</strong><p class="note">${result?I.productGroups(result).length+' 个商品 · '+all.length+' 条 SKU':'Excel .xlsx · 29 列模板 · 最多 5000 行'}</p></div><div class="row">${btn('product-file',busy?'正在读取…':'选择 Excel','upload','',busy?'disabled':'')}${btn('product-demo','载入示例','','ghost',busy?'disabled':'')}${btn('product-template','下载示例表','download','ghost')}</div></div>${result?`<div class="transfer-review-control"><div class="transfer-filter-bar"><div class="transfer-status-filters">${[['all','全部规格',filtered.length],['pending','待复核',pending],['ready','已确认',filtered.length-pending]].map(([k,label,count])=>`<button type="button" name="product-filter-${k}" class="transfer-filter-btn" data-action="product-filter" data-value="${k}" aria-pressed="${productFilter===k}">${label}<span>${count}</span></button>`).join('')}</div><div class="transfer-more-inline"><span id="product-extra-filters" ${productMore?'':'hidden'}>${productMore?`<button type="button" name="product-unwritten" class="transfer-filter-btn" data-action="product-unwritten" aria-pressed="${productUnwritten}">未写厚度<span>${all.filter(r=>!r.thicknessCandidates?.length).length}</span></button>`:''}</span><button type="button" name="product-more" class="transfer-filter-btn ${productMore?'transfer-collapse':''}" data-action="product-more" aria-expanded="${productMore}" aria-controls="product-extra-filters" aria-label="${productMore?'收起更多筛选':'更多筛选'}" title="${productMore?'收起更多筛选':productUnwritten?'已筛选未写厚度':'更多筛选'}">${productMore?'':'更多筛选'}${icon(productMore?'chevron-left':'chevron-right')}</button></div></div><div class="transfer-batch-tools"><span>已选 ${selectedProducts.size} 条</span>${btn('product-batch','批量处理所选','list-checks','',selectedProducts.size&&!busy?'':'disabled')}</div></div><div class="table-scroll" tabindex="0" aria-label="商品规格复核表，可横向滚动"><table class="transfer-review-table"><caption class="sr-only">按商品 ID 分组的材质、厚度、尺寸复核</caption><colgroup><col class="transfer-check"><col class="transfer-source"><col class="transfer-material"><col class="transfer-thickness"><col class="transfer-dimension"><col class="transfer-number"><col class="transfer-number"><col class="transfer-status"></colgroup><thead><tr><th><input type="checkbox" name="select-all" aria-label="选择当前页显示全部规格" ${shown.length&&shown.every(r=>selectedProducts.has(r.id))?'checked':''} ${shown.length?'':'disabled'}></th><th>原商品 / SKU 规格</th><th>材质</th><th>厚度 / mm</th><th>尺寸 / cm</th><th class="num">重量 / kg</th><th class="num">成本 / 元</th><th>状态</th></tr></thead><tbody>${body||'<tr><td colspan="8" class="table-empty">没有符合筛选条件的规格。</td></tr>'}</tbody></table></div><div class="transfer-footer"><span>显示 ${shown.length} / ${matching.length} 条 · 共 ${all.length} 条 · ${result.summary.pending?'还有 '+result.summary.pending+' 条待复核':'全部规格已确认，可导出'}</span>${pages>1?`<div class="review-pagination">${btn('product-prev','上一页','','ghost',productPage===0?'disabled':'')}<span>${productPage+1} / ${pages}</span>${btn('product-next','下一页','','ghost',productPage+1>=pages?'disabled':'')}</div>`:''}<span>同链接下拉选择应用于全部 SKU，尺寸保持原值。</span></div>`:empty('导入后自动识别，异常项集中复核','可先载入示例，体验同链接批量处理和未写厚度筛选。','product-demo','试用识别示例')}</section>`;
  }
  function captureProductBatch(){modal.batch=readForm();}
  function productBatchPatch(){const d=modal.batch,patch={};if(d.material!=='__keep')patch.material=d.material==='__blank'?'':d.material;if(d.dimensions!=='__keep'){const size=state.sizes.find(s=>s.id===d.dimensions);patch.dimensions=d.dimensions==='__blank'?null:d.dimensions==='__manual'?{width:Number(d.width),length:Number(d.length)}:{width:size?.salesW,length:size?.salesH};}if(d.thicknessRuleId!=='__keep')patch.thicknessRuleId=d.thicknessRuleId;return patch;}
  function productBatchImpact(){try{const out=I.previewProductReview(state.product,modal.ids,productBatchPatch(),state,modal.batch.overwrite==='on');dialog.querySelector('#product-batch-impact').textContent=`将更新 ${out.changed} 个 SKU：材质 ${out.counts.material} 项 / 厚度 ${out.counts.thickness} 项 / 尺寸 ${out.counts.dimension} 项。${out.protected?' 已确认字段受保护。':''}${out.incompatible?' '+out.incompatible+' 行材质不匹配或已留空，跳过厚度。':''}`;}catch(error){dialog.querySelector('#product-batch-impact').textContent=error.message;}}
  function productBatchForm(){
    const d=modal.batch||{material:'__keep',dimensions:'__keep',thicknessRuleId:'__keep',overwrite:''};modal.batch=d;
    const materialNames=state.materials.filter(m=>!m.deleted||state.product.rows.some(r=>modal.ids.includes(r.id)&&r.material===m.name));
    frame('批量处理所选规格',`<p class="note">已勾选 ${modal.ids.length} 个 SKU</p><div class="product-batch-fields">${select('材质','material',opt('__keep','保持原值',d.material)+opt('__blank','保留为空',d.material)+materialNames.map(m=>opt(m.name,m.name,d.material)).join(''))}${select('厚度','thicknessRuleId',opt('__keep','保持原值',d.thicknessRuleId)+materialNames.filter(m=>d.material==='__keep'||m.name===d.material).map(m=>`<optgroup label="${e(m.name)}">${transferRulesFor(m.name).map(r=>opt(r.id,m.name+' · '+ruleLabel(r),d.thicknessRuleId)).join('')}</optgroup>`).join(''))}${select('尺寸 / cm','dimensions',opt('__keep','保持原值',d.dimensions)+opt('__blank','保留为空',d.dimensions)+state.sizes.filter(s=>!s.irregular&&!s.deleted).map(s=>opt(s.id,M.sizeLabel(s),d.dimensions)).join('')+opt('__manual','手动输入…',d.dimensions))}</div>${d.dimensions==='__manual'?`<div class="dialog-grid stack-gap">${field('宽 / cm','width',d.width??'','number','min="0.01" max="10000" required')}${field('长 / cm','length',d.length??'','number','min="0.01" max="10000" required')}</div>`:''}<label class="checkbox-field stack-gap"><input type="checkbox" name="overwrite" ${d.overwrite==='on'?'checked':''}>同时覆盖已确认值（含人工选择与留空）</label><div id="product-batch-impact" class="help-box" aria-live="polite"></div>`,btn('close','取消')+'<button type="submit" class="btn primary">确认应用</button>',true);productBatchImpact();
  }
  function applyProductGroup(index,patch,focusName){
    if(conflict)throw Error('其他窗口已更新原型，请先重新载入');
    const group=I.productGroups(state.product)[index],before=R.clone(state.product.rows);
    const out=I.applyProductReview(state.product,group.rows.map(r=>r.id),patch,state,true);
    commit();productUndo={before,after:JSON.stringify(state.product.rows),materials:JSON.stringify(state.materials)};
    document.getElementsByName(focusName)[0]?.focus();toast('同链接 '+out.changed+' 个 SKU 已更新'+(out.incompatible?'，留空尺寸已跳过':''),true);
  }
  function ledgerTable(records){if(!records.length)return empty('还没有入账记录','填写测算后点击“确认入账”，保存当天的参数和结果。');return `<div class="table-scroll"><table class="history-table"><thead><tr><th>日期</th><th>店铺</th><th>广告消耗</th><th>销售额</th><th>预估盈亏</th><th>状态</th><th>操作</th></tr></thead><tbody>${[...records].reverse().map(r=>`<tr><td>${r.date}</td><td>${e(r.shopName)}</td><td>${money(r.snapshot.shops.find(s=>s.id===r.shopId).params.spend)}</td><td>${money(r.result.gmv)}</td><td class="${r.result.profit<0?'negative':'positive'}">${money(r.result.profit)}</td><td>${r.voided?'已作废':'已入账'}</td><td>${btn('record-view','明细','','ghost',`data-id="${r.id}"`)}${!r.voided?btn('record-void','作废','','ghost',`data-id="${r.id}"`):''}</td></tr>`).join('')}</tbody></table></div>`;}
  function chart(){const records=state.records.filter(r=>r.shopId===state.activeShop&&!r.voided).slice(-12);if(!records.length)return empty('入账后显示投入与利润','这里按已确认的每日记录绘制，不将当前试算当作历史数据。');const max=Math.max(1,...records.map(r=>Math.abs(r.result.profit)));return `<h2>每日预估盈亏</h2><div class="chart-bars">${records.map(r=>`<div><strong class="${r.result.profit<0?'negative':'positive'}">${money(r.result.profit)}</strong><div class="chart-bar" style="--bar-height:${Math.max(2,Math.abs(r.result.profit)/max*160)}px"></div><span>${r.date.slice(5)}</span></div>`).join('')}</div>`;}
  function ledgerPage(){const records=state.records.filter(r=>r.shopId===state.activeShop),active=records.filter(r=>!r.voided);return header('总账','当前店铺的原型入账记录，按入账时的价格和成本保留。',btn('ledger-export','导出账目','download'))+`<section class="wide-content"><div class="ledger-stats"><p>已入账<strong>${active.length} 天</strong></p><p>累计销售额<strong>${money(active.reduce((a,r)=>a+r.result.gmv,0))}</strong></p><p>累计预估盈亏<strong>${money(active.reduce((a,r)=>a+r.result.profit,0))}</strong></p></div>${ledgerTable(records)}</section>`;}
  function dataPage(){return header('备份与迁移','原型草稿独立保存，便于复核后继续修改。')+`<section class="wide-content"><section class="data-section"><h2>导出原型草稿</h2><p>保存全部店铺、定价方案、规则、商品转表复核结果和原型账目。可以在此原型中恢复。</p><div class="data-actions">${btn('backup','导出草稿','download','primary')}${btn('restore-file','恢复原型草稿','upload')}</div></section><section class="data-section"><h2>正式版数据</h2><p>本轮使用示例数据供复核，不连接正式数据库。正式版备份的迁移将在交互确认后接入。</p></section><section class="data-section"><h2>重新体验</h2><p>将本原型恢复到初始示例，清除当前原型草稿。正式版和其他旧原型不受影响。</p>${btn('reset','重置原型示例','rotate-ccw','danger')}</section></section>`;}
  function render(){window.ReviewPickers?.close();if(!state){app.innerHTML=`<main class="startup-error"><h1>原型草稿暂时无法读取</h1><p>${e(saveError)}</p>${btn('raw-backup','导出原始草稿')}${btn('reset','重置原型示例')}</main>`;return;}
    if(productUndo&&(productUndo.after!==JSON.stringify(state.product?.rows)||productUndo.materials!==JSON.stringify(state.materials))){productUndo=null;document.querySelector('#toast').classList.remove('show');document.querySelector('#toast').replaceChildren();}
    const title={work:'投放测算',library:'可复用规则',product:'商品转表',ledger:'总账',data:'备份与迁移'}[view];
    app.innerHTML=`<div class="app-shell">${nav()}<div class="workspace"><header class="topbar"><div class="crumbs"><span>${e(shop().name)}</span>${icon('chevron-right')}<strong>${title}</strong></div><div class="topbar-right"><span class="tag">修改复核原型</span><span role="status">${saveError?'草稿未保存':'已保存到本机'}</span>${ib('backup','导出原型草稿','download')}</div></header>${saveError?`<div id="save-banner"><div class="message-error">${e(saveError)}${btn('backup','导出草稿')}${btn('reload','重新载入')}</div></div>`:''}<main id="main-content">${view==='work'?workPage():view==='library'?libraryPage():view==='product'?productPageView():view==='ledger'?ledgerPage():dataPage()}</main></div></div>`;window.lucide?.createIcons();window.ReviewPickers?.refresh();if(view==='product'&&state.product){const shown=productSelection().shown,all=document.querySelector('[name=select-all]');all.indeterminate=selectedProducts.size>0&&selectedProducts.size<shown.length;I.productGroups(state.product).forEach((g,i)=>{const box=document.querySelector(`[data-product-group-select="${i}"]`),visible=g.rows.filter(r=>shown.some(x=>x.id===r.id));if(box)box.indeterminate=visible.some(r=>selectedProducts.has(r.id))&&!visible.every(r=>selectedProducts.has(r.id));});}}
  function close(){dialog.close();modal=null;if(focusBefore?.isConnected)focusBefore.focus();else document.querySelector('#main-content h1')?.focus();}
  function frame(title,body,footer,wide=false){dialog.className=wide?'wide':'';dialog.innerHTML=`<form id="modal-form"><div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2>${ib('close','关闭','x')}</div><div class="dialog-body">${body}<div class="modal-error" id="modal-error" role="alert"></div></div><div class="dialog-footer">${footer||btn('close','取消')+'<button type="submit" class="btn primary">保存</button>'}</div></form>`;window.lucide?.createIcons();if(!dialog.open)dialog.showModal();}
  function open(type,data={}){focusBefore=document.activeElement;modal={type,...data};paintModal();}
  function strategyForm(){const d=modal.draft;const opts=Object.entries(R.modes).map(([k,v])=>opt(k,v,d.mode)).join('');let fields='';if(d.mode==='area')fields=`${field('基准面积 / ㎡','baseArea',d.baseArea)}${field('基准毛利率 / %','baseMargin',d.baseMargin)}${field('每增加面积 / ㎡','stepArea',d.stepArea)}${field('毛利增加 / 个百分点','stepPoints',d.stepPoints)}${field('毛利率上限 / %','cap',d.cap)}`;if(d.mode==='fixed')fields=field('统一目标毛利率 / %','margin',d.margin);if(d.mode==='rank')fields=`<div class="field-full"><div class="row between"><h3>成本由低到高，同成本同档</h3>${btn('add-tier','增加一档','plus','ghost')}</div><div class="tiers-list">${d.tiers.map((v,i)=>field('第 '+(i+1)+' 档毛利 / %','tier-'+i,v)).join('')}</div>${d.tiers.length>1?btn('remove-tier','移除末档','','ghost'):''}</div>${field('其余档位毛利 / %','fallback',d.fallback)}`;
    frame(modal.isNew?'新增定价方案':'编辑定价方案',`<div class="dialog-grid"><div class="field-full">${field('方案名称','name',d.name,'text','required maxlength="80"')}</div>${select('策略类型','mode',opts)}${fields}</div><div id="strategy-preview">${strategyPreview(d)}</div><div class="help-box">同类型可保存多套方案。面积按完整档位递增，低于基准使用基准毛利。修改后只更新引用本方案的自动行，手动价保持。</div>`,btn('close','取消')+(!modal.isNew?btn('strategy-saveas','另存为新方案','copy'):'')+`<button type="submit" class="btn primary">${modal.isNew?'保存方案':'保存修改'}</button>`);}
  function strategyPreview(d){if(R.strategyErrors(d).length)return '<p class="note stack-gap">填写有效参数后预览目标毛利。</p>';const values=d.mode==='area'?[d.baseArea,d.baseArea+d.stepArea,d.baseArea+2*d.stepArea]:[.5,.6,.7];return `<div class="preview-grid">${values.map((a,i)=>`<div>${d.mode==='rank'?'成本第 '+(i+1)+' 档':n(a,2)+'㎡'}<strong>${n(R.target(d,a,i+1),1)}%</strong></div>`).join('')}</div>`;}
  function draftStrategy(){const f=dialog.querySelector('form'),d=modal.draft;for(const [k,v] of new FormData(f)){if(k.startsWith('tier-'))d.tiers[Number(k.slice(5))]=v===''?'':Number(v);else if(['name','mode'].includes(k))d[k]=v;else d[k]=v===''?'':Number(v);}return d;}
  function promotionLabel(step){return step.type==='discount'?`${step.discount} 折`:`直减 ${n(step.amount)} 元`;}
  function promotionSummary(s){return s?s.steps.map(promotionLabel).join(' → '):'无活动';}
  function draftPromotion(){const f=readForm(),d=modal.draft;d.name=f.name;d.steps=d.steps.map((old,i)=>{const type=f['promo-type-'+i],raw=f['promo-value-'+i],value=raw===''?'':Number(raw);return type==='discount'?{type,discount:old.type===type?value:9}:{type,amount:old.type===type?value:5};});return d;}
  function promotionPreview(d){const errors=P.errors({...d,name:d.name||'预览'});if(errors.length)return `<p class="note">${e(errors[0])}</p>`;const result=P.forward(100,{...d,name:d.name||'预览'});return `<span>以原价 ¥100.00 试算</span><strong>${result.steps.map(x=>money(x.after)).join(' → ')}</strong>`;}
  function promotionForm(){const d=modal.draft;return frame(modal.isNew?'新增活动方案':'编辑活动方案',`${field('方案名称','name',d.name,'text','required maxlength="80"')}<p class="note stack-gap">按顺序叠加，每一步基于上一步金额计算。9 折表示支付 90%。</p><div class="promotion-steps">${d.steps.map((step,i)=>`<div class="promotion-step"><span class="step-number">${i+1}</span>${select('活动类型','promo-type-'+i,opt('discount','折扣',step.type)+opt('reduction','直减',step.type))}${field(step.type==='discount'?'折扣 / 折':'直减金额 / 元','promo-value-'+i,step.type==='discount'?step.discount:step.amount,'number',`required min="0.01" max="${step.type==='discount'?10:1000000}"`)}<div class="row">${ib('promotion-up','上移第 '+(i+1)+' 项','arrow-up',`data-index="${i}" ${i===0?'disabled':''}`)}${ib('promotion-down','下移第 '+(i+1)+' 项','arrow-down',`data-index="${i}" ${i===d.steps.length-1?'disabled':''}`)}${ib('promotion-remove','移除第 '+(i+1)+' 项','x',`data-index="${i}"`)}</div></div>`).join('')}</div><div class="row promotion-add">${btn('promotion-add-discount','添加折扣','plus','ghost',d.steps.length>=10?'disabled':'')}${btn('promotion-add-reduction','添加直减','plus','ghost',d.steps.length>=10?'disabled':'')}</div><div id="promotion-preview" class="promotion-preview" aria-live="polite">${promotionPreview(d)}</div><p class="note stack-gap">金额逐步四舍五入到分。保存后更新选用此方案的上架价测算。</p>`,btn('close','取消')+(!modal.isNew?btn('promotion-saveas','另存为新方案','copy'):'')+'<button type="submit" class="btn primary">保存方案</button>');}
  function listingRows(){const scheme=state.promotionSchemes.find(x=>x.id===shop().promotionSchemeId)||{name:'无活动',steps:[{type:'discount',discount:10}]};return R.calculate(state).rows.map(row=>{const result=P.reverse(row.price,scheme);if(!shop().promotionSchemeId&&!result.error)result.steps=[];return {row,result};});}
  function listingCalculator(){const current=shop().promotionSchemeId,scheme=state.promotionSchemes.find(x=>x.id===current),rows=listingRows();return frame('上架价格计算器',`<div class="calculator-selection">${select('活动方案','promotionSchemeId',opt('','无活动',current)+state.promotionSchemes.filter(x=>!x.deleted||x.id===current).map(x=>opt(x.id,x.name+(x.deleted?'（已删除）':''),current)).join(''))}<p class="note">方案细则在「可复用规则 → 活动方案」中统一编辑。</p></div>${scheme?`<div class="activity-order">${e(promotionSummary(scheme))}</div>`:''}<p class="note calculator-caption">当前售价为最终到手价。一次选用活动方案，反推全部 SKU 的上架价。</p>${rows.length?`<div class="table-scroll"><table class="listing-table"><caption class="sr-only">全部 SKU 活动前上架价格</caption><thead><tr><th>商品规格</th><th class="num">目标到手价</th><th class="num">建议上架价</th><th class="num">核算到手价</th><th>计算明细</th></tr></thead><tbody>${rows.map(({row,result})=>`<tr data-listing-row="${row.id}"><td>${e(M.sizeLabel(row.size))}<div class="cell-meta">${e(row.skuId||'未绑定 SKU ID')}</div></td><td class="num">${money(row.price)}</td><td class="num listing-price">${money(result.listingPrice)}</td><td class="num">${money(result.finalPrice)}</td><td>${result.error?`<span class="negative">${e(result.error)}</span>`:result.steps.length?`<details class="listing-details"><summary>展开</summary><ol>${result.steps.map((step,i)=>`<li>${e(promotionLabel(scheme.steps[i]))}：${money(step.before)} → ${money(step.after)}</li>`).join('')}</ol></details>`:'—'}${!result.error&&!result.exact?`<div class="cell-meta">比目标高 ${money(result.difference)}</div>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有商品规格','添加规格并设置到手价后即可计算。')}<p class="note stack-gap">按金额逐步四舍五入到分，取活动后不低于目标到手价的最低上架价。结果仅用于上架，盈亏继续按到手价计算。</p>`,btn('close','关闭')+btn('listing-export','导出上架价格','download','primary',!rows.length||rows.some(x=>x.result.error)?'disabled':''),true);}
  function paintModal(){const d=modal;
    if(d.type==='promotion')return promotionForm();
    if(d.type==='listing-calculator')return listingCalculator();
    if(d.type==='plan-manage')return frame('管理计划',`<div class="table-scroll"><table class="plan-list"><thead><tr><th>计划名称</th><th>操作</th></tr></thead><tbody>${shop().plans.filter(p=>!p.deleted).map(p=>`<tr><td>${e(p.name)}${p.id===shop().activePlanId?' <span class="tag">当前</span>':''}</td><td>${ib('plan-rename','重命名 '+p.name,'pencil',`data-id="${p.id}"`)}${ib('plan-copy','复制 '+p.name,'copy',`data-id="${p.id}"`)}${ib('plan-delete','删除 '+p.name,'trash-2',`data-id="${p.id}"`)}</td></tr>`).join('')}</tbody></table></div>${shop().plans.some(p=>p.deleted)?`<details class="advanced stack-gap"><summary>已删除计划</summary><div class="plan-deleted-list">${shop().plans.filter(p=>p.deleted).map(p=>`<div class="row between"><span>${e(p.name)}</span>${btn('plan-restore','恢复','rotate-ccw','ghost',`data-id="${p.id}"`)}</div>`).join('')}</div></details>`:''}`,btn('close','关闭')+btn('plan-new','新建计划','plus','primary'));
    if(d.type==='plan-name')return frame(d.mode==='rename'?'重命名计划':d.mode==='copy'?'复制计划':'新建计划',field('计划名称','name',d.name,'text','required maxlength="80"'));
    if(d.type==='strategy')return strategyForm();
    if(d.type==='size-scheme-save')return frame('保存尺寸方案',`${field('方案名称','name','','text','required maxlength="80"')}<div class="help-box">${d.sizeIds.map(id=>e(sizeLabel(id))).join('、')}<br>仅保存尺寸组合，售价、占比和销售数据不包含在方案中。</div>`);
    if(d.type==='size-scheme'){const x=d.draft;return frame(d.isNew?'新增尺寸方案':'编辑尺寸方案',`${field('方案名称','name',x.name,'text','required maxlength="80"')}<div class="check-list stack-gap">${state.sizes.filter(s=>!s.deleted||x.sizeIds.includes(s.id)).map(s=>`<label><input type="checkbox" name="sizeId" value="${s.id}" ${x.sizeIds.includes(s.id)?'checked':''}>${e(M.sizeLabel(s))}${s.deleted?'（已删除）':''}</label>`).join('')}</div>`);}
    if(d.type==='columns'||d.type==='metrics'){const all=d.type==='columns'?R.columns:metricLabels,selected=d.type==='columns'?state.prefs.columns:state.prefs.metrics;return frame(d.type==='columns'?'商品规格显示设置':'指标显示设置',`<p class="note">${d.type==='columns'?'勾选要显示的列，毛利率按当前售价实时计算。':'选择 1–4 个常用指标。'}</p><div class="check-list">${Object.entries(all).map(([k,v])=>`<label><input type="checkbox" name="option" value="${k}" ${selected.includes(k)?'checked':''}>${v}</label>`).join('')}</div>`);}
    if(d.type==='sku'){const r=d.draft;return frame(d.isNew?'添加商品规格':'编辑商品规格',`<div class="dialog-grid">${select('尺寸','sizeId',state.sizes.filter(s=>!s.deleted||s.id===r.sizeId).map(s=>opt(s.id,M.sizeLabel(s)+(s.deleted?'（已删除）':''),r.sizeId)).join(''))}${select('材质','materialId',materialOptions(r.materialId))}${select('厚度规则','ruleId',rulesFor(r.materialId).map(t=>opt(t.id,ruleLabel(t),r.ruleId)).join(''))}${field('订单占比 / %','share',r.share,'number','min="0" max="100"')}${field('商品 ID','productId',r.productId,'text')}${field('SKU ID','skuId',r.skuId,'text')}${field('实测发货重量 / g（可留空）','weightGrams',r.weightGrams,'number','min="0.001"')}${!shop().strategyId?field('售价 / 元','manualPrice',r.manualPrice,'number','min="0.01"'):''}</div><div class="help-box">新增规格跟随当前定价方案。实测重量留空时，按面积与材料规则自动计算。</div>`);}
    if(d.type==='material'){const m=d.draft;return frame(d.isNew?'新增材料':'编辑材料与规则',`${field('材料名称','name',m.name,'text','required')}<div class="tiers-list">${m.weightRules.map((r,i)=>`<div class="help-box"><strong>${e(ruleLabel(r))}</strong>${field('厚度 / mm（可空）','thickness-'+i,r.thickness)}${field('成本 / 元每㎡','cost-'+i,r.costPerSqm,'number','min="0" required')}${field('重量系数 / kg每㎡','weight-'+i,r.coefficient,'number','min="0" required')}</div>`).join('')}</div><p class="note stack-gap">保存后更新相关自动价与当前商品转表计算，历史账目保持。</p>`);}
    if(d.type==='size'){const s=d.draft;return frame(d.isNew?'新增尺寸':'编辑尺寸',`<div class="dialog-grid">${field('销售宽 / cm','salesW',s.salesW,'number','min="0.01" max="10000" required')}${field('销售长 / cm','salesH',s.salesH,'number','min="0.01" max="10000" required')}${select('形状','irregular',opt('false','矩形',String(s.irregular))+opt('true','异形',String(s.irregular)))}${field('规格名称（异形必填）','name',s.name,'text')}${field('生产宽 / cm（异形填写）','productionW',s.productionW)}${field('生产长 / cm（异形填写）','productionH',s.productionH)}</div>`);}
    if(d.type==='shipping')return frame(d.isNew?'新增固定运费模板':'编辑运费模板',`<div class="dialog-grid">${field('模板名称','name',d.draft.name,'text','required')}${field('每单运费 / 元','fee',d.draft.fee,'number','min="0" required')}</div>`);
    if(d.type==='dimension')return frame('手动填写尺寸',`<p class="note">${e(d.row.originalSpec)}</p><div class="dialog-grid">${field('宽 / cm','width',d.row.dimensions?.width??'','number','required min="0.01" max="10000"')}${field('长 / cm','length',d.row.dimensions?.length??'','number','required min="0.01" max="10000"')}</div>`);
    if(d.type==='batch')return productBatchForm();
    if(d.type==='sales')return salesModal();
    if(d.type==='entry')return frame('确认原型入账',`<div class="dialog-grid">${field('入账日期','date',M.today(),'date','required max="'+M.today()+'"')}${field('备注','note','','text')}</div><div class="help-box">${e(shop().name)} · 整体成交金额 ${money(R.calculate(state).gmv)} · 预估盈亏 ${money(R.calculate(state).profit)}。保存当时参数与价格，后续修改策略不改历史账目。</div>`,btn('close','取消')+'<button type="submit" class="btn primary">确认入账</button>');
    if(d.type==='new-shop')return frame('新增店铺',field('店铺名称','name','','text','required maxlength="80"'));
    if(d.type==='confirm')return frame(d.title,`<p class="inline-info">${e(d.message)}</p>`,btn('close','取消')+'<button type="submit" class="btn primary">确认</button>');
    if(d.type==='record'){const r=d.record;return frame('入账明细 · '+r.date,`<p class="note">${e(r.shopName)} · ${e(r.note||'无备注')}</p><div class="ledger-stats"><p>销售额<strong>${money(r.result.gmv)}</strong></p><p>预估盈亏<strong>${money(r.result.profit)}</strong></p></div><div class="table-scroll"><table><thead><tr><th>规格</th><th>售价</th><th>占比</th><th>毛利率</th></tr></thead><tbody>${r.result.rows.map(x=>`<tr><td>${e(M.sizeLabel(x.size))}</td><td>${money(x.price)}</td><td>${n(x.share)}%</td><td>${n(x.margin)}%</td></tr>`).join('')}</tbody></table></div>`,btn('close','关闭'));}
    if(d.type==='changes')return frame('本轮修改',`<div class="stack inline-info"><p>1. 每家店独立管理计划，支持删除和恢复。</p><p>2. SKU 可显示毛利率。</p><p>3. 三种策略类型，支持多套方案编辑、保存与另存。</p><p>4. 本地销售表自动匹配 SKU，回填销量与订单占比。</p><p>5. 材质 / 尺寸分别复核，允许确认留空。伪亚麻必须人工确认。</p><p>6. 移除统一包装重量输入。</p></div>`,btn('close','开始检查'));
  }
  function salesModal(){if(!salesDraft)return frame('导入销售情况',`<div class="upload-panel"><div><strong>选择 SKU 销售报表</strong><p>自动识别 SKU ID、订单数 / 件数与统计周期。</p></div>${btn('sales-file','选择 Excel','upload')}</div><p class="note">推荐按支付订单数计算占比。报表只有件数时，需要明确确认按件数估算。不会覆盖售价。</p><div class="data-actions">${btn('sales-demo','试用销售示例','flask-conical')}${btn('sales-template','下载示例表','download','ghost')}</div>`,btn('close','关闭'));
    const d=salesDraft,matched=d.items.filter(x=>x.match&&!x.error&&!x.excluded).length;
    frame('复核销售导入',`<p class="note">${e(d.filename)} · ${d.items.length} 条 · ${matched} 条已匹配。重复导入替换当前销量，不重复累计。</p><div class="sales-map">${Object.entries(d.map).filter(([,v])=>v>=0).map(([k,v])=>`<span>${{shop:'店铺',skuId:'SKU ID',productId:'商品 ID',spec:'规格',count:'数量',period:'周期'}[k]} ← ${e(d.headers[v])}</span>`).join('')}</div><div class="dialog-grid">${field('统计周期','period',d.period,'text','required')}${select('报表未出现的 SKU','missing',opt('keep','待确认，不自动视作 0',d.missing)+opt('zero','本次测算按 0 处理',d.missing))}</div>${d.basis==='件数'?`<label class="checkbox-field"><input type="checkbox" name="allowUnits" ${d.allowUnits?'checked':''}>按件数估算订单占比（一单一件假设）</label>`:''}<div class="table-scroll stack-gap"><table class="sales-table"><thead><tr><th>原 SKU / 规格</th><th>数量（${d.basis}）</th><th>匹配商品规格</th><th>排除</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${e(x.sku||x.spec)}${x.error?`<div class="row-error">${e(x.error)}</div>`:''}</td><td>${e(x.count)}</td><td><select name="match-${x.id}" aria-label="匹配 ${e(x.sku||x.spec)}">${opt('','待匹配',x.match)}${shop().rows.map(r=>opt(r.id,sizeLabel(r.sizeId)+' · '+r.skuId,x.match)).join('')}</select></td><td><input type="checkbox" name="exclude-${x.id}" aria-label="排除 ${e(x.sku||x.spec)}" ${x.excluded?'checked':''}></td></tr>`).join('')}</tbody></table></div><p class="note stack-gap">未匹配记录需选定规格或明确排除后应用。销售数量合计为 0 时，不生成占比。</p>`,btn('sales-file','重新选择','upload')+btn('close','取消')+'<button type="submit" class="btn primary">应用销量与占比</button>',true);
  }
  function modalError(err){const el=document.querySelector('#modal-error');if(el){el.textContent=err.message||String(err);el.scrollIntoView({block:'nearest'});}else toast(err.message||String(err));}
  function readForm(){return Object.fromEntries(new FormData(dialog.querySelector('form')));}
  function strategyOpen(existing,copy=false){const d=existing?R.clone(existing):{id:'',name:'',mode:'area',baseArea:.5,baseMargin:10,stepArea:.1,stepPoints:1,cap:40,margin:30,tiers:[10,15,20],fallback:25,active:true,round:'cent'};Object.assign(d,{tiers:d.tiers||[10,15,20],baseArea:d.baseArea??.5,baseMargin:d.baseMargin??10,stepArea:d.stepArea??.1,stepPoints:d.stepPoints??1,cap:d.cap??40,margin:d.margin??30,fallback:d.fallback??25});if(copy){d.id='';d.name+=' · 副本';}open('strategy',{draft:d,isNew:!existing||copy});}
  async function submit(){const f=readForm(),d=modal;if(d.type==='strategy'){R.saveStrategy(state,draftStrategy(),d.isNew);close();commit('定价方案已保存');return;}
    if(d.type==='promotion'){R.savePromotionScheme(state,draftPromotion(),d.isNew);close();commit('活动方案已保存');return;}
    if(d.type==='plan-name'){const name=f.name.trim();if(!name)throw Error('请填写计划名称');if(d.mode==='rename'){if(shop().plans.some(p=>p.id!==d.id&&!p.deleted&&p.name===name))throw Error('已有同名计划');shop().plans.find(p=>p.id===d.id).name=name;}else{if(shop().plans.some(p=>!p.deleted&&p.name===name))throw Error('已有同名计划');if(d.mode==='copy')R.switchPlan(state,shop(),d.id);R.createPlan(state,shop(),name,d.mode==='copy');}undoSales=null;}
    if(d.type==='size-scheme-save')R.saveSizeScheme(state,{name:f.name,sizeIds:d.sizeIds},true);
    if(d.type==='size-scheme'){const sizeIds=new FormData(dialog.querySelector('form')).getAll('sizeId');R.saveSizeScheme(state,{...d.draft,name:f.name,sizeIds},d.isNew);}
    if(d.type==='columns'||d.type==='metrics'){const values=new FormData(dialog.querySelector('form')).getAll('option');if(!values.length||d.type==='metrics'&&values.length>4)throw Error(d.type==='metrics'?'请选择 1–4 个指标':'请至少显示一列');state.prefs[d.type==='columns'?'columns':'metrics']=values;}
    if(d.type==='sku'){const row={...d.draft,...f,share:Number(f.share),weightGrams:f.weightGrams===''?'':Number(f.weightGrams)};if(f.manualPrice!==undefined)row.manualPrice=Number(f.manualPrice);if(!M.nonnegative(row.share)||row.share>100)throw Error('订单占比需为 0–100%');if(row.weightGrams!==''&&!M.positive(row.weightGrams))throw Error('实测重量需为正数或留空');if(!rulesFor(row.materialId).some(r=>r.id===row.ruleId))throw Error('请选择有效厚度规则');if(row.skuId&&shop().rows.some(r=>r.id!==row.id&&r.skuId===row.skuId&&r.productId===row.productId))throw Error('该商品下的 SKU ID 已存在');if(d.isNew)shop().rows.push(row);else Object.assign(shop().rows.find(r=>r.id===row.id),row);}
    if(d.type==='material'){const m=R.clone(d.draft);m.name=f.name.trim();if(!m.name||state.materials.some(x=>x.id!==m.id&&x.name===m.name))throw Error('材料名称不能为空或重复');m.weightRules.forEach((r,i)=>{r.thickness=f['thickness-'+i]===''?'':Number(f['thickness-'+i]);r.costPerSqm=Number(f['cost-'+i]);r.coefficient=Number(f['weight-'+i]);if(!M.nonnegative(r.costPerSqm)||!M.nonnegative(r.coefficient)||r.thickness!==''&&!M.positive(r.thickness))throw Error('请填写有效成本、厚度和重量系数');});if(d.isNew)state.materials.push(m);else{const previous=state.materials.find(x=>x.id===m.id),oldName=previous.name;Object.assign(previous,m);for(const row of state.product?.rows||[])if(row.materialStatus==='value'&&row.material===oldName)row.material=m.name;}if(state.product)I.recalculateProducts(state.product,state);}
    if(d.type==='size'){const s={...d.draft,...f,irregular:f.irregular==='true'};for(const k of ['salesW','salesH','productionW','productionH'])s[k]=f[k]===''?'':Number(f[k]);if(!M.validSize(s)||(s.irregular&&!s.name.trim()))throw Error('请填写有效尺寸，异形还需名称和生产长宽');if(d.isNew)state.sizes.push(s);else Object.assign(state.sizes.find(x=>x.id===s.id),s);}
    if(d.type==='shipping'){const t={...d.draft,name:f.name.trim(),fee:Number(f.fee)};if(!t.name||!M.validTemplate(t))throw Error('请输入有效模板名称和运费');if(d.isNew)state.shippingTemplates.push(t);else Object.assign(state.shippingTemplates.find(x=>x.id===t.id),t);}
    if(d.type==='dimension'){const dimensions={width:Number(f.width),length:Number(f.length)};if(![dimensions.width,dimensions.length].every(x=>x>0&&x<=10000&&Number.isFinite(x)))throw Error('长宽需为有效正数');I.reviewProduct(state.product,[d.row.id],{dimensions},state);}
    if(d.type==='batch'){captureProductBatch();I.applyProductReview(state.product,d.ids,productBatchPatch(),state,d.batch.overwrite==='on');selectedProducts.clear();}
    if(d.type==='sales'){if(!salesDraft)return;const next=R.clone(salesDraft);next.period=f.period;next.missing=f.missing;next.allowUnits=f.allowUnits==='on';next.items.forEach(x=>{x.match=f['match-'+x.id];x.excluded=f['exclude-'+x.id]==='on';});const before={shopId:shop().id,rows:R.clone(shop().rows),source:R.clone(shop().salesSource)};I.applySales(next,shop());undoSales=before;salesDraft=null;state.prefs.columns=[...new Set([...state.prefs.columns,'sales'])];}
    if(d.type==='entry')R.makeRecord(state,f.date,f.note);
    if(d.type==='new-shop'){if(state.shops.some(s=>s.name===f.name.trim()))throw Error('已有同名店铺');const s={...R.clone(shop()),id:R.id('shop'),name:f.name.trim(),rows:[],salesSource:null};s.params.spend=s.params.actualRoi='';delete s.plans;delete s.activePlanId;const migrated=R.migrate({...state,shops:[s],activeShop:s.id,records:[]});state.shops.push(migrated.shops[0]);state.activeShop=s.id;}
    if(d.type==='confirm'){await d.run();close();commit();return;}
    close();commit(d.type==='sales'?'销量与订单占比已更新，售价保持':'已保存');
  }
  function choose(kind){fileKind=kind;fileInput.accept=kind==='restore'?'.json':'.xlsx';fileInput.value='';fileInput.click();}
  function confirmAction(title,message,run){open('confirm',{title,message,run});}
  app.addEventListener('click',event=>handleClick(event));dialog.addEventListener('click',event=>handleClick(event));document.querySelector('#toast').addEventListener('click',event=>handleClick(event));
  async function handleClick(event){const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();if(busy&&el.dataset.action!=='close')return;const a=el.dataset.action,id=el.dataset.id;
    try{
      if(a==='close')return close();if(a==='menu'){menuOpen=!menuOpen;return render();}if(a==='reload')return location.reload();
      if(a==='nav'){view=el.dataset.view;menuOpen=false;render();window.scrollTo(0,0);return;}if(a==='tab'){tab=el.dataset.tab;return render();}if(a==='library-tab'){libTab=el.dataset.tab;return render();}
      if(a==='listing-calculator')return open('listing-calculator');
      if(a==='listing-export'){const s=state.promotionSchemes.find(x=>x.id===shop().promotionSchemeId),rows=listingRows();if(!rows.length||rows.some(x=>x.result.error))throw Error('请先补齐有效到手价');const data=[['商品规格','SKU ID','活动方案','目标到手价','建议上架价','核算到手价','活动叠加顺序'],...rows.map(x=>[M.sizeLabel(x.row.size),x.row.skuId,s?.name||'无活动',x.row.price,x.result.listingPrice,x.result.finalPrice,promotionSummary(s)])];download(await I.simpleWorkbook(data,'上架价格'),'SKU上架价格.xlsx');return toast('上架价格已导出');}
      if(['promotion-new','promotion-edit','promotion-copy'].includes(a)&&view==='library'){const existing=state.promotionSchemes.find(x=>x.id===id),draft=existing?R.clone(existing):{name:'',steps:[{type:'discount',discount:9}]};if(a==='promotion-copy'){draft.id='';draft.name+=' · 副本';}return open('promotion',{draft,isNew:a!=='promotion-edit'});}
      if(a==='promotion-saveas'){draftPromotion();modal.draft.id='';modal.draft.name+=' · 副本';modal.isNew=true;return paintModal();}
      if(['promotion-add-discount','promotion-add-reduction','promotion-remove','promotion-up','promotion-down'].includes(a)){const d=draftPromotion(),index=Number(el.dataset.index);if(a.startsWith('promotion-add')){if(d.steps.length>=10)throw Error('最多叠加 10 项活动');d.steps.push(a==='promotion-add-discount'?{type:'discount',discount:9}:{type:'reduction',amount:5});}else if(a==='promotion-remove')d.steps.splice(index,1);else{const to=index+(a==='promotion-up'?-1:1);if(to>=0&&to<d.steps.length)[d.steps[index],d.steps[to]]=[d.steps[to],d.steps[index]];}return paintModal();}
      if(a==='plan-manage')return open('plan-manage');
      if(['plan-new','plan-copy','plan-rename'].includes(a)){const p=shop().plans.find(p=>p.id===id);return open('plan-name',{mode:a==='plan-copy'?'copy':a==='plan-rename'?'rename':'new',id,name:p?p.name+(a==='plan-copy'?' · 副本':''):''});}
      if(a==='plan-delete'){const p=shop().plans.find(p=>p.id===id);return confirmAction('删除计划？',`“${p.name}”将移至已删除计划，已入账数据保留，可在管理计划中恢复。`,()=>{R.deletePlan(state,shop(),id);undoSales=null;});}
      if(a==='plan-restore'){R.restorePlan(state,shop(),id);persist();paintModal();render();return toast('计划已恢复');}
      if(a==='sku-options'){skuOptionsOpen=!skuOptionsOpen;return render();}
      if(a==='size-scheme-save'){const sizeIds=[...new Set(shop().rows.map(r=>r.sizeId))];if(!sizeIds.length)throw Error('请先添加商品规格');return open('size-scheme-save',{sizeIds});}
      if(['size-scheme-new','size-scheme-edit','size-scheme-copy'].includes(a)){const existing=state.sizeSchemes.find(x=>x.id===id),draft=existing?R.clone(existing):{id:'',name:'',sizeIds:[]};if(a==='size-scheme-copy'){draft.id='';draft.name+=' · 副本';}return open('size-scheme',{draft,isNew:a!=='size-scheme-edit'});}
      if(a==='rule-delete'){const kind=el.dataset.kind,item=state[kind].find(x=>x.id===id);return confirmAction('删除这份规则？',`“${item.name||M.sizeLabel(item)}”将从可选列表移除，已有引用和历史账目保留；可在已删除列表恢复。`,()=>R.deleteReusable(state,kind,id));}
      if(a==='rule-restore'){R.restoreReusable(state,el.dataset.kind,id);return commit('已恢复');}
      if(a==='changes')return open('changes');if(a==='columns'||a==='metrics')return open(a);
      if(a==='strategy-new'){if(view!=='library')return;return strategyOpen();}if((a==='strategy-edit'||a==='strategy-copy')&&view==='library')return strategyOpen(state.strategies.find(s=>s.id===id),a==='strategy-copy');
      if(a==='strategy-saveas'){const draft=draftStrategy();draft.id='';draft.name+=' · 副本';modal.isNew=true;return paintModal();}
      if(a==='add-tier'||a==='remove-tier'){draftStrategy();if(a==='add-tier'){if(modal.draft.tiers.length>=20)throw Error('最多支持 20 档');modal.draft.tiers.push(modal.draft.fallback);}else modal.draft.tiers.pop();return paintModal();}
      if(a==='strategy-toggle'){const s=state.strategies.find(s=>s.id===id);s.active=!s.active;return commit(s.active?'方案已启用':'已停用，现有引用继续保留');}
      if(a==='restore-price'){shop().rows.find(r=>r.id===id).priceMode='auto';return commit('已恢复当前方案价格');}
      if(a==='restore-all')return confirmAction('全部恢复策略价','当前店铺的手动售价将按所选方案重新计算。',()=>shop().rows.forEach(r=>r.priceMode='auto'));
      if(a==='normalize'){R.normalizeShares(shop());return commit('订单占比已调整为 100%');}
      if(a==='add-sku'||a==='edit-sku'){if(a==='add-sku'&&!state.sizes.some(x=>!x.deleted))throw Error('请先在可复用规则中添加尺寸');const s=shop(),row=a==='edit-sku'?R.clone(s.rows.find(r=>r.id===id)):{id:R.id('row'),sizeId:state.sizes.find(x=>!x.deleted).id,materialId:s.materialId,ruleId:s.ruleId,productId:'',skuId:'',priceMode:s.strategyId?'auto':'manual',manualPrice:'',weightGrams:'',share:0,sales:null};return open('sku',{draft:row,isNew:a==='add-sku'});}
      if(a==='remove-sku')return confirmAction('移除商品规格','移除当前测算行，历史入账保持。',()=>shop().rows=shop().rows.filter(r=>r.id!==id));
      if(a==='material-edit'||a==='material-new'){const draft=a==='material-edit'?R.clone(state.materials.find(m=>m.id===id)):{id:R.id('material'),name:'',price:0,active:true,deleted:false,weightRules:[{id:R.id('rule'),thickness:'',variant:'',costPerSqm:10,coefficient:1,default:true}]};return open('material',{draft,isNew:a==='material-new'});}
      if(a==='size-new'||a==='size-edit')return open('size',{draft:a==='size-edit'?R.clone(state.sizes.find(s=>s.id===id)):{id:R.id('size'),name:'',salesW:50,salesH:100,irregular:false,productionW:'',productionH:'',active:true,deleted:false},isNew:a==='size-new'});
      if(a==='shipping-library'){view='library';libTab='shipping';return render();}if(a==='shipping-new'||a==='shipping-edit')return open('shipping',{draft:a==='shipping-edit'?R.clone(state.shippingTemplates.find(t=>t.id===id)):{id:R.id('shipping'),name:'',type:'fixed',fee:2,active:true,deleted:false},isNew:a==='shipping-new'});
      if(a==='new-shop')return open('new-shop');if(a==='entry'){const r=R.calculate(state);if(!r.valid||r.profit===null)throw Error('请先补齐测算参数、售价和订单占比');return open('entry');}
      if(a==='record-view')return open('record',{record:state.records.find(r=>r.id===id)});if(a==='record-void')return confirmAction('作废入账记录','该条记录保留明细，作废后不参与累计。',()=>state.records.find(r=>r.id===id).voided=true);
      if(a==='sales'){salesDraft=null;return open('sales');}if(a==='sales-file')return choose('sales');
      if(a==='sales-demo'){salesDraft=I.analyzeSales(I.salesExample(shop()),shop(),state);salesDraft.filename='SKU销售情况-示例.xlsx';return paintModal();}
      if(a==='sales-template')return download(await I.simpleWorkbook(I.salesExample(shop()),'SKU销售情况'),'SKU销售情况-示例.xlsx');
      if(a==='undo-sales'){const s=shop();if(undoSales?.shopId!==s.id)return;for(const row of s.rows){const old=undoSales.rows.find(r=>r.id===row.id);if(old){row.sales=old.sales;row.share=old.share;}}s.salesSource=undoSales.source;undoSales=null;return commit('已撤销本次销量与占比');}
      if(a==='product-file')return choose('product');if(a==='product-demo'){const run=()=>{state.product=I.analyzeProducts(I.integratedProductExample(),state);state.product.filename='商品规格-识别示例.xlsx';selectedProducts.clear();productPage=0;productFilter='all';productUnwritten=false;productMore=false;productUndo=null;};if(state.product)return confirmAction('载入识别示例','替换当前原型转表草稿，原始 Excel 文件不受影响。',run);run();return commit('已载入识别示例');}
      if(a==='product-template')return download(await I.simpleWorkbook(I.productExample(),'商品规格'),'商品规格-识别示例.xlsx');
      if(a==='product-batch')return open('batch',{ids:[...selectedProducts]});if(a==='product-prev'||a==='product-next'){productPage+=a==='product-next'?1:-1;return render();}
      if(a==='product-filter'){productFilter=el.dataset.value;productPage=0;render();document.getElementsByName(el.name)[0]?.focus();return;}
      if(a==='product-more'){productMore=!productMore;render();document.getElementsByName(el.name)[0]?.focus();return;}
      if(a==='product-unwritten'){productUnwritten=!productUnwritten;productPage=0;render();document.getElementsByName(el.name)[0]?.focus();return;}
      if(a==='product-undo'){if(!productUndo)return;state.product.rows=productUndo.before;productUndo=null;I.recalculateProducts(state.product,state);commit('已撤销本次同链接修改');return;}
      if(a==='product-export'){busy=true;render();try{const response=await fetch('assets/product-template.xlsx');if(!response.ok)throw Error('内置模板读取失败');const bytes=await I.exportProducts(state.product,state,await response.arrayBuffer());download(bytes,'商品转表-复核原型.xlsx');toast('商品表已导出，确认留空保留为空单元格');}finally{busy=false;render();}return;}
      if(a==='backup')return download(JSON.stringify(state,null,2),'地垫工作台-复核草稿.json','application/json');if(a==='raw-backup')return download(savedRaw||'','原型原始草稿.json','application/json');if(a==='restore-file')return choose('restore');
      if(a==='reset')return confirmAction('重置原型示例','清除当前原型草稿并恢复初始示例。正式版数据保持。',()=>{state=R.seed();conflict=false;savedRaw=localStorage.getItem(R.KEY);selectedProducts.clear();view='work';});
      if(a==='ledger-export'){const rows=[['日期','店铺','整体成交金额','预估盈亏','状态'],...state.records.filter(r=>r.shopId===state.activeShop).map(r=>[r.date,r.shopName,r.result.gmv,r.result.profit,r.voided?'已作废':'已入账'])];return download(await I.simpleWorkbook(rows,'原型账目'),'原型账目.xlsx');}
    }catch(err){console.error(err);modal?modalError(err):toast(err.message);}
  }
  document.addEventListener('change',event=>{
    const el=event.target;if(!state)return;
    try{
      if(dialog.contains(el)){
        if(modal?.type==='batch'&&['material','dimensions','thicknessRuleId','overwrite'].includes(el.name)){captureProductBatch();if(el.name==='material')modal.batch.thicknessRuleId='__keep';if(el.name==='overwrite'){productBatchImpact();return;}productBatchForm();dialog.querySelector(`[name="${el.name}"]`)?.focus();return;}
        if(modal?.type==='listing-calculator'&&el.name==='promotionSchemeId'){R.selectPromotionScheme(state,shop(),el.value);persist();paintModal();render();return;}
        if(modal?.type==='promotion'&&el.name.startsWith('promo-type-')){draftPromotion();paintModal();return;}
        if(modal?.type==='strategy'&&el.name==='mode'){draftStrategy();paintModal();return;}
        if(modal?.type==='sku'&&el.name==='materialId'){Object.assign(modal.draft,readForm());modal.draft.ruleId=rulesFor(el.value).find(r=>r.default)?.id||rulesFor(el.value)[0]?.id;paintModal();return;}
        return;
      }
      if(el.name==='showDeletedRules'){showDeletedRules=el.checked;render();return;}
      if(el.name==='sizeSchemeId'){if(!el.value)return;const scheme=state.sizeSchemes.find(x=>x.id===el.value);const added=R.applySizeScheme(state,shop(),scheme.id);commit(`已选用“${scheme.name}”，新增 ${added} 个尺寸`);return;}
      if(el.id==='active-plan'){R.switchPlan(state,shop(),el.value);undoSales=null;commit();return;}
      if(el.id==='active-shop'){state.activeShop=el.value;undoSales=null;commit();return;}
      if(el.name==='strategyId'){R.switchStrategy(state,shop(),el.value);commit('已切换方案，手动售价保持');return;}
      if(el.dataset.param){const v=el.value===''?'':Number(el.value);if(v!==''&&(!M.nonnegative(v)||el.max&&v>Number(el.max)))throw Error('请输入有效的非负数');const dest=el.dataset.refund?shop().params.refundRates:shop().params;dest[el.dataset.param]=v;commit();return;}
      if(el.dataset.row){const row=shop().rows.find(r=>r.id===el.dataset.row),v=el.value===''?'':Number(el.value);if(el.dataset.key==='price'){if(!M.positive(v))throw Error('售价需大于 0');row.manualPrice=v;row.priceMode='manual';}else{if(!M.nonnegative(v)||v>100)throw Error('占比需为 0–100%');row.share=v;}commit(el.dataset.key==='price'?'该 SKU 已切换为手动售价':'');return;}
      if(el.name==='defaultMaterial'){const s=shop(),old=s.materialId;s.materialId=el.value;s.ruleId=rulesFor(el.value).find(r=>r.default)?.id||rulesFor(el.value)[0].id;for(const row of s.rows.filter(r=>r.materialId===old)){row.materialId=s.materialId;row.ruleId=s.ruleId;}commit();return;}
      if(el.name==='defaultRule'){const s=shop();s.ruleId=el.value;for(const row of s.rows.filter(r=>r.materialId===s.materialId))row.ruleId=s.ruleId;commit();return;}
      if(el.name==='shippingId'){shop().shippingId=el.value;commit();return;}
      if(el.dataset.productGroupSelect!==undefined){const group=I.productGroups(state.product)[Number(el.dataset.productGroupSelect)],visible=new Set(productSelection().shown.map(r=>r.id));for(const r of group.rows.filter(r=>visible.has(r.id)))el.checked?selectedProducts.add(r.id):selectedProducts.delete(r.id);render();return;}
      if(el.dataset.productGroupMaterial!==undefined){if(el.value==='__mixed')return;applyProductGroup(Number(el.dataset.productGroupMaterial),{material:el.value==='__blank'?'':el.value},el.name);return;}
      if(el.dataset.productGroupThickness!==undefined){if(el.value==='__pending')return;applyProductGroup(Number(el.dataset.productGroupThickness),{thicknessRuleId:el.value},el.name);return;}
      if(el.dataset.selected){el.checked?selectedProducts.add(el.dataset.selected):selectedProducts.delete(el.dataset.selected);render();return;}
      if(el.name==='select-all'){document.querySelectorAll('[data-selected]').forEach(x=>el.checked?selectedProducts.add(x.dataset.selected):selectedProducts.delete(x.dataset.selected));render();return;}
      if(el.dataset.productMaterial){if(el.value==='__pending'){render();return;}I.reviewProduct(state.product,[el.dataset.productMaterial],{material:el.value==='__blank'?'':el.value},state);commit();return;}
      if(el.dataset.productDimension){const r=state.product.rows.find(r=>r.id===el.dataset.productDimension);if(el.value==='__manual'){open('dimension',{row:r});render();return;}if(['__pending','__value'].includes(el.value)){render();return;}const c=r.dimensionCandidates[Number(el.value)];I.reviewProduct(state.product,[r.id],{dimensions:el.value==='__blank'?null:{width:c.width,length:c.length}},state);commit();}
      if(el.dataset.productThickness){if(el.value==='__pending'){render();return;}I.reviewProduct(state.product,[el.dataset.productThickness],{thicknessRuleId:el.value},state);commit('厚度已确认，重量与成本已重算');return;}
    }catch(err){el.setAttribute('aria-invalid','true');toast(err.message);}
  });
  dialog.addEventListener('input',event=>{if(modal?.type==='batch'&&['width','length'].includes(event.target.name)){captureProductBatch();productBatchImpact();}if(modal?.type==='promotion'&&!event.target.name.startsWith('promo-type-')){draftPromotion();dialog.querySelector('#promotion-preview').innerHTML=promotionPreview(modal.draft);}if(modal?.type==='strategy'&&event.target.name!=='mode'){draftStrategy();dialog.querySelector('#strategy-preview').innerHTML=strategyPreview(modal.draft);}});
  dialog.addEventListener('submit',event=>{event.preventDefault();if(busy)return;Promise.resolve(submit()).catch(modalError);});
  dialog.addEventListener('cancel',()=>{modal=null;});
  fileInput.addEventListener('change',async()=>{const file=fileInput.files[0];if(!file)return;const kind=fileKind;busy=true;try{
    if(file.size>15*1024*1024)throw Error('文件超过 15 MB，请拆分后导入');
    if(kind==='restore'){const next=R.migrate(JSON.parse(await file.text()));if(!R.validState(next))throw Error('不是有效的本轮原型草稿');confirmAction('恢复原型草稿','将替换当前原型草稿，正式版数据保持。',()=>{localStorage.setItem(R.KEY+'-before-restore',JSON.stringify(state));state=next;selectedProducts.clear();});return;}
    const rows=await I.readRows(await file.arrayBuffer());
    if(kind==='sales'){salesDraft=I.analyzeSales(rows,shop(),state);salesDraft.filename=file.name;modal={type:'sales'};paintModal();}
    if(kind==='product'){const result=I.analyzeProducts(rows,state);result.filename=file.name;state.product=result;selectedProducts.clear();productFilter='all';productPage=0;productUnwritten=false;productMore=false;productUndo=null;commit('已导入，请复核材质、厚度与尺寸');}
  }catch(err){modal?modalError(err):toast(err.message);}finally{busy=false;render();fileInput.value='';}});
  window.addEventListener('storage',event=>{if(event.key===R.KEY&&event.newValue!==savedRaw){conflict=true;saveError='其他窗口已更新原型，请导出本页草稿后重新载入。';render();}});
  if(state&&(!savedRaw||JSON.stringify(state)!==savedRaw)){try{if(savedRaw&&!localStorage.getItem(R.KEY+'-before-rules-upgrade'))localStorage.setItem(R.KEY+'-before-rules-upgrade',savedRaw);persist();}catch(err){saveError='旧草稿升级未保存：'+err.message;}}render();
})();
